            for(Peptide peptide: protein2ms2peptide.get(proID).get(spectrum_id)){

                if(CParameter.search_type.equals(CParameter.SearchType.known)){
                    if(this.target_peptides.contains(peptide.getSequence())){
                        continue;
                    }
